/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: TopSearch
 * Internal
 *   Constants: SearchTypeahead
 * @end-catalog */

import {
  lazy,
  Suspense,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type FocusEvent,
  type FormEvent,
  type KeyboardEvent,
  type MouseEvent
} from 'react';
import { Icon } from '../components/Icon';
import type { TypeaheadOption } from '../features/search/SearchTypeahead';
import { useSearchQuery } from '../features/search/SearchQueryProvider';
import { useSearchHistoryRecorder } from '../features/search/useSearchHistoryRecorder';
import { useLocalization } from '../localization/LocalizationProvider';
import styles from './AppShell.module.css';

// The suggestion panel loads on first use so the always-present shell stays light.
const SearchTypeahead = lazy(() => import('../features/search/SearchTypeahead'));

/**
 * Owns the shell search field. On wide layouts away from the Search route it is an ARIA 1.2
 * combobox whose inline suggestions keep the current route; otherwise typing opens Search.
 */
export default function TopSearch() {
  const input = useRef<HTMLInputElement>(null);
  const listboxId = useId();
  const { recordSubmittedQuery } = useSearchHistoryRecorder();
  const {
    commitDraft,
    draftQuery,
    finishComposition,
    isComposing,
    startComposition,
    typeaheadActive,
    typeaheadQuery,
    updateDraft
  } = useSearchQuery();
  const { t } = useLocalization();
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const [optionCount, setOptionCount] = useState(0);
  const options = useRef<TypeaheadOption[]>([]);
  const showTypeahead = typeaheadActive && open;
  const expanded = showTypeahead && optionCount > 0;

  useEffect(() => {
    setActiveIndex(-1);
  }, [typeaheadQuery]);

  useEffect(() => {
    if (!typeaheadActive) setOpen(false);
  }, [typeaheadActive]);

  const close = useCallback(() => {
    setOpen(false);
    setActiveIndex(-1);
  }, []);

  const registerOptions = useCallback((next: TypeaheadOption[]) => {
    options.current = next;
    setOptionCount(next.length);
    setActiveIndex((index) => (index < next.length ? index : -1));
  }, []);

  // A chosen suggestion has moved on (opened a route or started playback), so release the field.
  const finishSuggestion = useCallback(() => {
    close();
    input.current?.blur();
  }, [close]);

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isComposing) return;
    const highlighted = showTypeahead && activeIndex >= 0 ? options.current[activeIndex] : undefined;
    if (highlighted) {
      highlighted.activate();
      return;
    }
    close();
    const normalized = commitDraft();
    if (normalized) recordSubmittedQuery(normalized);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' && (event.nativeEvent.isComposing || event.keyCode === 229)) {
      event.preventDefault();
      return;
    }
    if (!typeaheadActive) return;
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      if (!open) {
        setOpen(true);
        return;
      }
      const count = options.current.length;
      if (count === 0) return;
      setActiveIndex((index) => {
        if (event.key === 'ArrowDown') return (index + 1) % count;
        return index <= 0 ? count - 1 : index - 1;
      });
    } else if (event.key === 'Escape' && open) {
      event.preventDefault();
      close();
    }
  };

  // Suggestions are not focusable, so focus leaving the form means the listener moved elsewhere.
  const handleBlur = (event: FocusEvent<HTMLFormElement>) => {
    if (!event.currentTarget.contains(event.relatedTarget as Node | null)) close();
  };

  const expandCompactSearch = (event: MouseEvent<HTMLButtonElement>) => {
    if (window.matchMedia?.('(max-width: 479px)').matches && document.activeElement !== input.current) {
      event.preventDefault();
      input.current?.focus();
    }
  };

  return (
    <form
      className={styles.search}
      role="search"
      aria-label={t('shell.search.global_label')}
      onBlur={handleBlur}
      onSubmit={submit}
    >
      <button
        className={styles.searchSubmit}
        onClick={expandCompactSearch}
        type="submit"
        aria-label={t('shell.search.submit_label')}
      >
        <Icon name="search" />
      </button>
      <label className="visually-hidden" htmlFor="shell-search">{t('shell.search.field_label')}</label>
      <input
        aria-activedescendant={expanded && activeIndex >= 0 ? `${listboxId}-option-${activeIndex}` : undefined}
        aria-autocomplete={typeaheadActive ? 'list' : undefined}
        aria-controls={expanded ? listboxId : undefined}
        aria-expanded={typeaheadActive ? expanded : undefined}
        autoComplete="off"
        enterKeyHint="search"
        id="shell-search"
        name="q"
        onChange={(event) => {
          updateDraft(event.currentTarget.value);
          if (typeaheadActive) setOpen(true);
        }}
        onCompositionEnd={(event) => finishComposition(event.currentTarget.value)}
        onCompositionStart={startComposition}
        onFocus={() => {
          if (typeaheadActive) setOpen(true);
        }}
        onKeyDown={handleKeyDown}
        placeholder={t('shell.search.placeholder')}
        ref={input}
        role={typeaheadActive ? 'combobox' : undefined}
        type="search"
        value={draftQuery}
      />
      {showTypeahead && (
        <Suspense fallback={null}>
          <SearchTypeahead
            activeIndex={activeIndex}
            listboxId={listboxId}
            onActiveIndexChange={setActiveIndex}
            onDone={finishSuggestion}
            onOptionsChange={registerOptions}
            query={typeaheadQuery}
          />
        </Suspense>
      )}
    </form>
  );
}
